import{_ as o,C as n,o as t,c as d,ah as r,b as s,w as a,a as l,E as c,ai as u}from"./chunks/framework.Sdx4l2LO.js";const f=JSON.parse('{"title":"M13: Runtime Survival, HMR Hardening & Concurrent Instances","description":"","frontmatter":{},"headers":[],"relativePath":"specs/M13-runtime-survival-hmr-concurrency.md","filePath":"specs/M13-runtime-survival-hmr-concurrency.md","lastUpdated":1774839561000}'),h={name:"specs/M13-runtime-survival-hmr-concurrency.md"};function m(p,e,g,b,D,y){const i=n("Mermaid");return t(),d("div",null,[e[1]||(e[1]=r('<h1 id="m13-runtime-survival-hmr-hardening-concurrent-instances" tabindex="-1">M13: Runtime Survival, HMR Hardening &amp; Concurrent Instances <a class="header-anchor" href="#m13-runtime-survival-hmr-hardening-concurrent-instances" aria-label="Permalink to &quot;M13: Runtime Survival, HMR Hardening &amp; Concurrent Instances&quot;">​</a></h1><p><strong>Status</strong>: Draft <strong>Created</strong>: 2026-03-29 <strong>Author</strong>: DINOForge Agents <strong>Priority</strong>: P0 (critical path for runtime reliability) <strong>Depends on</strong>: M1 (Runtime Scaffold), M3 (Dev Tooling), MCP Bridge</p><hr><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>DINOForge is a mod platform for Diplomacy is Not an Option (DINO), a Unity 2021.3 ECS game. The runtime injects via BepInEx and provides:</p><ul><li>Named pipe bridge server (GameBridgeServer) for CLI/MCP tool communication</li><li>ModPlatform orchestrator (pack loading, registries, content pipeline)</li><li>UI overlays (F9 debug, F10 mod menu, main menu Mods button)</li><li>Hot reload via FileSystemWatcher + HMR signal file</li><li>Asset swap system for visual model replacement</li></ul><h3 id="root-problems-identified" tabindex="-1">Root Problems Identified <a class="header-anchor" href="#root-problems-identified" aria-label="Permalink to &quot;Root Problems Identified&quot;">​</a></h3><ol><li><p><strong>RuntimeDriver destruction</strong>: DINO&#39;s scene management destroys HideAndDontSave GameObjects during scene transitions via Unity&#39;s native C++ <code>Object::Destroy</code> (bypasses C# Harmony patches). This kills the bridge server, UI components, and file watchers.</p></li><li><p><strong>MainThreadDispatcher dead pump</strong>: MainThreadDispatcher uses <code>MonoBehaviour.Update()</code> to drain work enqueued from background threads. But DINO replaces Unity&#39;s entire PlayerLoop, so <code>MonoBehaviour.Update()</code> NEVER fires. Queries requiring main-thread access (entity count, world name) time out.</p></li><li><p><strong>HMR fragility</strong>: Hot reload watcher thread gets aborted during scene transitions. FileSystemWatcher and HMR signal file mechanism need to survive independently of MonoBehaviour lifecycle.</p></li><li><p><strong>Single-instance limitation</strong>: Unity&#39;s native mutex prevents concurrent game instances from the same directory. Current workaround (copy game to <code>_TEST</code> dir) is manual and fragile.</p></li></ol><hr><h2 id="deliverables" tabindex="-1">Deliverables <a class="header-anchor" href="#deliverables" aria-label="Permalink to &quot;Deliverables&quot;">​</a></h2><h3 id="d1-ecs-based-main-thread-pump" tabindex="-1">D1: ECS-Based Main Thread Pump <a class="header-anchor" href="#d1-ecs-based-main-thread-pump" aria-label="Permalink to &quot;D1: ECS-Based Main Thread Pump&quot;">​</a></h3><ul><li>Move MainThreadDispatcher queue drain from <code>MonoBehaviour.Update()</code> to a new ECS <code>SystemBase.OnUpdate()</code></li><li>ECS systems survive DINO&#39;s scene transitions (proven by KeyInputSystem)</li><li><code>SystemBase.OnUpdate()</code> fires reliably during gameplay (SimulationSystemGroup)</li><li>At main menu, use a dedicated InitializationSystemGroup system for pump</li><li><strong>Acceptance</strong>: <code>game_status</code> CLI command returns entity count + world name within 1 second</li></ul><h3 id="d2-bridge-server-thread-immunity" tabindex="-1">D2: Bridge Server Thread Immunity <a class="header-anchor" href="#d2-bridge-server-thread-immunity" aria-label="Permalink to &quot;D2: Bridge Server Thread Immunity&quot;">​</a></h3><ul><li>Bridge server thread must not be aborted during scene transitions</li><li>Current finding: both <code>IsBackground=true</code> and <code>IsBackground=false</code> threads are aborted ~23s after RuntimeDriver destruction</li><li>Investigation: determine if thread abort is caused by (a) Mono GC finalizer, (b) Unity engine cleanup, or (c) thread holding references to destroyed Unity objects</li><li>Solution options: (i) catch <code>ThreadAbortException</code> and restart thread, (ii) move thread creation to static constructor, (iii) use <code>System.Net.Sockets</code> instead of <code>NamedPipeServerStream</code></li><li><strong>Acceptance</strong>: bridge responds to <code>status</code> query 60+ seconds after game reaches main menu</li></ul><h3 id="d3-runtimedriver-resurrection-via-ecs" tabindex="-1">D3: RuntimeDriver Resurrection via ECS <a class="header-anchor" href="#d3-runtimedriver-resurrection-via-ecs" aria-label="Permalink to &quot;D3: RuntimeDriver Resurrection via ECS&quot;">​</a></h3><ul><li>When PersistentRoot is destroyed, <code>KeyInputSystem.OnCreate</code> (new ECS world) triggers TryResurrect</li><li>TryResurrect attaches new RuntimeDriver to DINO&#39;s main camera (survives transitions)</li><li>If camera not available, create new <code>DINOForge_Root</code> with <code>HideAndDontSave</code></li><li><strong>Acceptance</strong>: <code>RuntimeDriver.OnDestroy</code> log followed by successful resurrection log + bridge reconnects</li></ul><h3 id="d4-hmr-system-hardening" tabindex="-1">D4: HMR System Hardening <a class="header-anchor" href="#d4-hmr-system-hardening" aria-label="Permalink to &quot;D4: HMR System Hardening&quot;">​</a></h3><ul><li>Move HMR signal file watcher to a static thread (not tied to RuntimeDriver)</li><li>FileSystemWatcher for pack YAML changes -&gt; static singleton, survives destruction</li><li>HMR signal: write <code>DINOForge_HotReload</code> file to BepInEx dir -&gt; runtime detects + reloads</li><li>Pack hot reload: detect YAML changes -&gt; <code>ContentLoader.Reload()</code> -&gt; registry update -&gt; stat reapply</li><li><strong>Acceptance</strong>: modify a pack YAML while at main menu -&gt; log shows reload without game restart</li></ul><h3 id="d5-n-parallel-concurrent-instance-support" tabindex="-1">D5: N-Parallel Concurrent Instance Support <a class="header-anchor" href="#d5-n-parallel-concurrent-instance-support" aria-label="Permalink to &quot;D5: N-Parallel Concurrent Instance Support&quot;">​</a></h3><ul><li>Automate TEST instance creation: copy game dir -&gt; patch <code>boot.config</code> -&gt; remove mutex DLL</li><li>MCP tool <code>game_launch_test(n=2)</code> -&gt; launch N independent instances</li><li>Each instance gets unique named pipe: <code>dinoforge-game-bridge-{instance_id}</code></li><li>CLI/MCP tools accept <code>--instance &lt;id&gt;</code> to target specific game</li><li><strong>Acceptance</strong>: 2 game instances running simultaneously, each queryable via CLI</li></ul><h3 id="d6-qol-agent-experience-ax" tabindex="-1">D6: QOL -- Agent Experience (AX) <a class="header-anchor" href="#d6-qol-agent-experience-ax" aria-label="Permalink to &quot;D6: QOL -- Agent Experience (AX)&quot;">​</a></h3><ul><li><code>/validate-runtime</code> slash command: build -&gt; deploy -&gt; launch -&gt; verify bridge -&gt; verify packs -&gt; verify F9/F10 -&gt; report</li><li>Unified <code>/eval-all</code> with <code>--live</code> flag that includes runtime validation</li><li>MCP health endpoint returns bridge status, main-thread pump status, loaded pack count</li><li>Auto-recovery: if bridge thread dies, ECS system restarts it on next OnUpdate</li><li>Structured JSON error responses from bridge (not just &quot;Failed to execute&quot;)</li></ul><h3 id="d7-qol-user-experience-ux" tabindex="-1">D7: QOL -- User Experience (UX) <a class="header-anchor" href="#d7-qol-user-experience-ux" aria-label="Permalink to &quot;D7: QOL -- User Experience (UX)&quot;">​</a></h3><ul><li>Mods button visible and clickable on main menu (requires D3 resurrection)</li><li>F10 mod menu shows loaded packs with enable/disable toggles</li><li>F9 debug overlay shows entity count, FPS, pack status, swap results</li><li>Desktop Companion shows real-time bridge status (connected/disconnected)</li><li>Installer validates BepInEx version compatibility before install</li></ul><h3 id="d8-qol-modder-experience-modderx" tabindex="-1">D8: QOL -- Modder Experience (ModderX) <a class="header-anchor" href="#d8-qol-modder-experience-modderx" aria-label="Permalink to &quot;D8: QOL -- Modder Experience (ModderX)&quot;">​</a></h3><ul><li><code>dinoforge new-pack &lt;name&gt;</code> CLI scaffolds pack with manifest + directories</li><li><code>dinoforge validate &lt;pack&gt;</code> reports all schema violations with line numbers</li><li>Hot reload feedback: toast notification in-game when pack YAML changes detected</li><li>Asset swap status: F9 overlay shows N/M swaps succeeded with failure reasons</li><li>Pack conflict detection at load time with actionable error messages</li></ul><h3 id="d9-qol-developer-experience-dx" tabindex="-1">D9: QOL -- Developer Experience (DX) <a class="header-anchor" href="#d9-qol-developer-experience-dx" aria-label="Permalink to &quot;D9: QOL -- Developer Experience (DX)&quot;">​</a></h3><ul><li><code>dotnet build -p:DeployToGame=true</code> deploys DLL + packs in one command (already works)</li><li>Lefthook pre-push runs build + 1327 tests (already works)</li><li><code>dinoforge dev-harness --watch</code> auto-rebuilds on C# changes + HMR signal</li><li>Debug log rotation: cap <code>dinoforge_debug.log</code> at 10MB, rotate to <code>.1</code>, <code>.2</code></li><li>Structured logging: JSON-line format option for machine-parseable debug output</li></ul><hr><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Deliverable</th><th>Blocked By</th><th>Priority</th></tr></thead><tbody><tr><td>D1 (ECS pump)</td><td>None</td><td><strong>P0 -- blocks everything</strong></td></tr><tr><td>D2 (Bridge thread)</td><td>None</td><td><strong>P0 -- blocks everything</strong></td></tr><tr><td>D3 (Resurrection)</td><td>D1</td><td>P1</td></tr><tr><td>D4 (HMR hardening)</td><td>D2</td><td>P1</td></tr><tr><td>D5 (N-parallel)</td><td>D2</td><td>P2</td></tr><tr><td>D6 (AX QOL)</td><td>D1, D2, D3</td><td>P2</td></tr><tr><td>D7 (UX QOL)</td><td>D3</td><td>P1</td></tr><tr><td>D8 (ModderX QOL)</td><td>D4</td><td>P2</td></tr><tr><td>D9 (DX QOL)</td><td>None</td><td>P3</td></tr></tbody></table>',31)),(t(),s(u,null,{default:a(()=>[c(i,{id:"mermaid-454",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20D1%5BD1%3A%20ECS%20Pump%3Cbr%3EP0%5D%20--%3E%20D3%5BD3%3A%20Resurrection%3Cbr%3EP1%5D%0A%20%20%20%20D2%5BD2%3A%20Bridge%20Thread%3Cbr%3EP0%5D%20--%3E%20D4%5BD4%3A%20HMR%20Hardening%3Cbr%3EP1%5D%0A%20%20%20%20D2%20--%3E%20D5%5BD5%3A%20N-Parallel%3Cbr%3EP2%5D%0A%20%20%20%20D3%20--%3E%20D7%5BD7%3A%20UX%20QOL%3Cbr%3EP1%5D%0A%20%20%20%20D1%20--%3E%20D6%5BD6%3A%20AX%20QOL%3Cbr%3EP2%5D%0A%20%20%20%20D2%20--%3E%20D6%0A%20%20%20%20D3%20--%3E%20D6%0A%20%20%20%20D4%20--%3E%20D8%5BD8%3A%20ModderX%20QOL%3Cbr%3EP2%5D%0A%20%20%20%20D9%5BD9%3A%20DX%20QOL%3Cbr%3EP3%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<hr><h2 id="acceptance-criteria-summary" tabindex="-1">Acceptance Criteria Summary <a class="header-anchor" href="#acceptance-criteria-summary" aria-label="Permalink to &quot;Acceptance Criteria Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Test</th><th>Method</th><th>Pass Criteria</th></tr></thead><tbody><tr><td>Bridge alive after 60s</td><td><code>dinoforge status</code> via CLI</td><td>Returns JSON with <code>Running=true</code></td></tr><tr><td>Entity count returned</td><td><code>dinoforge status</code> via CLI</td><td><code>EntityCount &gt; 0</code> (not -1)</td></tr><tr><td>Mods button visible</td><td>Screenshot + VLM</td><td>&quot;Mods&quot; text visible on main menu</td></tr><tr><td>F9 overlay toggles</td><td>F9 keypress + screenshot</td><td>Debug overlay visible</td></tr><tr><td>Hot reload works</td><td>Modify YAML + log check</td><td>&quot;HotReload&quot; in debug log</td></tr><tr><td>2 instances run</td><td>2x game process + 2x status</td><td>Both return <code>Running=true</code></td></tr><tr><td>Pack validate</td><td><code>dinoforge validate packs/</code></td><td>Exit code 0, no schema errors</td></tr><tr><td>1327 tests pass</td><td><code>dotnet test</code></td><td>All green</td></tr></tbody></table><hr><h2 id="technical-notes" tabindex="-1">Technical Notes <a class="header-anchor" href="#technical-notes" aria-label="Permalink to &quot;Technical Notes&quot;">​</a></h2><ul><li>DINO uses Unity 2021.3.45f2, full ECS (DOTS), Burst, Mono runtime</li><li><code>MonoBehaviour.Update()</code> NEVER fires -- DINO replaces Unity&#39;s PlayerLoop</li><li>ECS <code>SystemBase.OnUpdate()</code> DOES fire reliably during gameplay</li><li><code>SceneManager.LoadScene()</code> destroys all objects including HideAndDontSave via native C++</li><li>Background threads created from MonoBehaviour scope get aborted ~23s after destruction</li><li>Harmony patches on <code>Object.Destroy</code> / <code>Object.DestroyImmediate</code> don&#39;t intercept native destruction</li><li>Named pipe (<code>NamedPipeServerStream</code>) is the IPC mechanism for CLI/MCP bridge</li><li>F9/F10 work via Win32 <code>GetAsyncKeyState</code> on a background thread + KeyInputSystem ECS callbacks</li></ul><hr><h2 id="risk-register" tabindex="-1">Risk Register <a class="header-anchor" href="#risk-register" aria-label="Permalink to &quot;Risk Register&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Risk</th><th>Impact</th><th>Mitigation</th></tr></thead><tbody><tr><td>ECS world destroyed on scene change</td><td>D1/D3 pump stops</td><td>Resurrection re-registers system on new world creation</td></tr><tr><td>Thread abort root cause is Unity engine-level</td><td>D2 bridge dies</td><td>Fall back to static constructor + socket-based IPC</td></tr><tr><td>Mutex removal breaks game saves</td><td>D5 data corruption</td><td>Each instance uses isolated save directory</td></tr><tr><td>HMR reload triggers during gameplay</td><td>D4 instability</td><td>Queue reloads, apply only at safe points (pause/menu)</td></tr><tr><td>N-parallel disk space</td><td>D5 ~8GB per copy</td><td>Symlink shared assets, copy only DLLs + config</td></tr></tbody></table><hr><h2 id="implementation-order" tabindex="-1">Implementation Order <a class="header-anchor" href="#implementation-order" aria-label="Permalink to &quot;Implementation Order&quot;">​</a></h2><ol><li><strong>Sprint 1 (P0)</strong>: D1 + D2 in parallel -- establish reliable main-thread pump and immortal bridge thread</li><li><strong>Sprint 2 (P1)</strong>: D3 + D4 + D7 -- resurrection, HMR hardening, and user-facing UI</li><li><strong>Sprint 3 (P2)</strong>: D5 + D6 + D8 -- concurrent instances, agent QOL, modder QOL</li><li><strong>Sprint 4 (P3)</strong>: D9 -- developer QOL polish</li></ol><hr><h2 id="success-metric" tabindex="-1">Success Metric <a class="header-anchor" href="#success-metric" aria-label="Permalink to &quot;Success Metric&quot;">​</a></h2><p>M13 is complete when: a DINOForge-modded game survives a full session (main menu -&gt; gameplay -&gt; pause -&gt; resume -&gt; exit) with bridge responding to CLI queries at every stage, hot reload working without restart, and a second concurrent instance queryable in parallel.</p>',15))])}const S=o(h,[["render",m]]);export{f as __pageData,S as default};
